def paginate(items,page,size):
    total = len(items)
    if total == 0:
        return {items:list, total:total, pages:0}
    pages = [1]
    if size <= 0:
        raise ValueError("size must be a positive integer")
    if page <= 0:
        raise ValueError("page must be a positive integer")
    for i in range(page - 1):
        pages.append(i + 1)
    for i in range(page, total):
        if i % size == 0 and i != 0:
            pages.append(i)
        if i - pages[-1] == size - 1:
            break
    pages = pages[:]
    if page > pages[-1]:
        return {items:list, total:total, pages:pages[:]}
    items = [items[i - pages[i - 1] * size: i - pages[i - 1] * size + size] for i in range(page, len(items)) if i % size == 0 and i != 0 else i]
    # Filter to only complete pages
    items = [items[i] for i in range(page, min(pages[-1] * size, len(items)) * size) if i % size == 0 and i != 0 or (i - pages[i - 1] * size) % size == 0 and i != pages[-1]]
    return {items:list, total:total, pages:pages[:]}

